// ---- Forward pass ---------------------------------------------------
// Accepts 14 raw sensor features in 'x', writes denormalised Vmp (V) to out[0].
// All intermediate buffers are stack-allocated; safe for ESP32-S3.
static inline void vmpForwardPass(const float* x, float* out) {
    float a[32], b[16], c[8];
    int i, j;

    // Normalise inputs
    float xn[VMP_N_FEATURES];
    for (i = 0; i < VMP_N_FEATURES; i++)
        xn[i] = (x[i] - VMP_INPUT_MEAN[i]) / VMP_INPUT_STD[i];

    // Dense 1: 14 -> 32
    for (j = 0; j < 32; j++) {
        float s = VMP_D1_B[j];
        for (i = 0; i < 14; i++) s += xn[i] * VMP_D1_W[i * 32 + j];
        a[j] = s;
    }
    // BN 1
    for (j = 0; j < 32; j++) {
        float v = (a[j] - VMP_BN1_MEAN[j]) / sqrtf(VMP_BN1_VAR[j] + VMP_BN1_EPS);
        a[j] = v * VMP_BN1_GAMMA[j] + VMP_BN1_BETA[j];
    }
    // ReLU 1
    for (j = 0; j < 32; j++) a[j] = a[j] > 0.0f ? a[j] : 0.0f;

    // Dense 2: 32 -> 16
    for (j = 0; j < 16; j++) {
        float s = VMP_D2_B[j];
        for (i = 0; i < 32; i++) s += a[i] * VMP_D2_W[i * 16 + j];
        b[j] = s;
    }
    // BN 2
    for (j = 0; j < 16; j++) {
        float v = (b[j] - VMP_BN2_MEAN[j]) / sqrtf(VMP_BN2_VAR[j] + VMP_BN2_EPS);
        b[j] = v * VMP_BN2_GAMMA[j] + VMP_BN2_BETA[j];
    }
    // ReLU 2
    for (j = 0; j < 16; j++) b[j] = b[j] > 0.0f ? b[j] : 0.0f;

    // Dense 3: 16 -> 8
    for (j = 0; j < 8; j++) {
        float s = VMP_D3_B[j];
        for (i = 0; i < 16; i++) s += b[i] * VMP_D3_W[i * 8 + j];
        c[j] = s;
    }
    // BN 3
    for (j = 0; j < 8; j++) {
        float v = (c[j] - VMP_BN3_MEAN[j]) / sqrtf(VMP_BN3_VAR[j] + VMP_BN3_EPS);
        c[j] = v * VMP_BN3_GAMMA[j] + VMP_BN3_BETA[j];
    }
    // ReLU 3
    for (j = 0; j < 8; j++) c[j] = c[j] > 0.0f ? c[j] : 0.0f;

    // Dense 4: 8 -> 1 (linear)
    float s = VMP_D4_B[0];
    for (i = 0; i < 8; i++) s += c[i] * VMP_D4_W[i];

    // Denormalise output
    out[0] = s * VMP_TARGET_STD + VMP_TARGET_MEAN;
}

